    const btnDirect = document.getElementById('btn-direct');
    const btnReset = document.getElementById('btn-reset');

    const TOTAL_SALARY = 8500;
    const SVG_WIDTH = 600;
    const START_X = 50;
    const END_X = 650;

    function update(val) {
        // 磁吸效应：当滑块接近5000元时，自动吸附到5000元，便于教学操作
        if (val >= 4700 && val <= 5300) {
            val = 5000;
            slider.value = 5000;
        }

        sliderVal.textContent = val;

        // 计算分割点在SVG中的X坐标
        const splitX = START_X + (val / TOTAL_SALARY) * SVG_WIDTH;

        // 更新进度条宽度和位置
        leftBar.setAttribute('width', splitX - START_X);
        rightBar.setAttribute('x', splitX);
        rightBar.setAttribute('width', END_X - splitX);

        // 更新分割线位置
        divider.setAttribute('x1', splitX);
        divider.setAttribute('x2', splitX);

        // 更新区间标注线 (Dimension Lines)
        leftDim.setAttribute('d', `M 50,120 L 50,130 M 50,125 L ${splitX},125 M ${splitX},120 L ${splitX},130`);
        rightDim.setAttribute('d', `M ${splitX},120 L ${splitX},130 M ${splitX},125 L 650,125 M 650,120 L 650,130`);

        // 更新区间文本位置与内容
        leftLabel.setAttribute('x', (START_X + splitX) / 2);
        rightLabel.setAttribute('x', (splitX + END_X) / 2);

        // 边界处理：防止文本重叠
        if (val < 800) {
            leftLabel.setAttribute('display', 'none');
            leftDim.setAttribute('display', 'none');
        } else {
            leftLabel.setAttribute('display', 'inline');
            leftDim.setAttribute('display', 'inline');
        }

        if (TOTAL_SALARY - val < 800) {
            rightLabel.setAttribute('display', 'none');
            rightDim.setAttribute('display', 'none');
        } else {
            rightLabel.setAttribute('display', 'inline');
            rightDim.setAttribute('display', 'inline');
        }

        // 隐藏警示横幅
        alertBanner.style.display = 'none';

        // 核心教学逻辑判断
        if (val === 5000) {
            // 正确划分起征点
            leftBar.setAttribute('fill', '#2e7d32'); // 绿色：免税
            rightBar.setAttribute('fill', '#ef6c00'); // 橙色：纳税
            rightBar.classList.add('pulse');

            leftLabel.textContent = "免税部分：5000 元";
            rightLabel.textContent = "超出部分(应纳税)：3500 元";
            leftLabel.setAttribute('fill', '#2e7d32');
            rightLabel.setAttribute('fill', '#e65100');

            feedbackText.innerHTML = '🎉 <span style="color: var(--success-color);">非常正确！</span> 5000元以内的部分免税，超出5000元的部分才按3%交税。';
            formulaBox.style.display = 'block';
            formulaBox.innerHTML = '(8500 - 5000) × 3% = 105 (元)';
        } else {
            // 普通拖动状态
            leftBar.setAttribute('fill', '#90caf9'); // 蓝色
            rightBar.setAttribute('fill', '#b0bec5'); // 灰色
            rightBar.classList.remove('pulse');

            leftLabel.textContent = `${val} 元`;
            rightLabel.textContent = `${TOTAL_SALARY - val} 元`;
            leftLabel.setAttribute('fill', '#1565c0');
            rightLabel.setAttribute('fill', '#37474f');

            feedbackText.innerHTML = '请继续拖动滑块，寻找国家规定的 <span style="color: var(--warning-color);">5000元</span> 起征点。';
            formulaBox.style.display = 'none';
        }
    }

    // 监听滑块输入
    slider.addEventListener('input', (e) => {
        update(parseInt(e.target.value));
    });

    // 错误概念警示按钮
    btnDirect.addEventListener('click', () => {
        formulaBox.style.display = 'none';
        alertBanner.style.display = 'block';
        alertBanner.innerHTML = '⚠️ 注意：不能直接用 8500 × 3% 哦！<br>因为 5000 元以内的工资是免税的。如果直接乘，李阿姨就多交了 5000 × 3% = 150 元的冤枉税！';

        // 触发抖动动画
        alertBanner.style.animation = 'none';
        alertBanner.offsetHeight; /* 触发重绘 */
        alertBanner.style.animation = 'shake 0.5s ease-in-out';
    });

    // 重置按钮
    btnReset.addEventListener('click', () => {
        slider.value = 0;
        update(0);
    });

    // 初始化页面
    update(0);
