<script>
    // 状态变量
    let leftTax = 9;   // 9 或 30
    let rightTax = 50; // 10 或 50

    // DOM 元素
    const movableGroup = document.getElementById('movable-group');
    const leftPanGroup = document.getElementById('left-pan-group');
    const rightPanGroup = document.getElementById('right-pan-group');
    const harmonyGlow = document.getElementById('harmony-glow');

    const btnLeftLow = document.getElementById('btn-left-low');
    const btnLeftHigh = document.getElementById('btn-left-high');
    const btnRightLow = document.getElementById('btn-right-low');
    const btnRightHigh = document.getElementById('btn-right-high');

    const leftStatusCard = document.getElementById('left-status-card');
    const leftStatusTitle = document.getElementById('left-status-title');
    const leftStatusDesc = document.getElementById('left-status-desc');

    const rightStatusCard = document.getElementById('right-status-card');
    const rightStatusTitle = document.getElementById('right-status-title');
    const rightStatusDesc = document.getElementById('right-status-desc');

    const guidanceText = document.getElementById('guidance-text');

    // 物理常量
    const centerX = 250;
    const centerY = 130;
    const armLength = 150; // 半臂长

    // 更新天平物理状态
    function updatePhysicalScale() {
        // 计算目标倾角 (度)
        // 设想：
        // 1. 左低(9) 右高(50) -> 最优社会状态，天平平衡 (0度)
        // 2. 左高(30) 右高(50) -> 百姓负担重，左边重 (倾斜 -10度)
        // 3. 左低(9) 右低(10) -> 烟草泛滥，右边社会危害重 (倾斜 10度)
        // 4. 左高(30) 右低(10) -> 双重糟糕，天平剧烈失衡 (倾斜 -5度，且显示警告)

        let angle = 0;
        if (leftTax === 9 && rightTax === 50) {
            angle = 0;
        } else if (leftTax === 30 && rightTax === 50) {
            angle = -10; // 左倾
        } else if (leftTax === 9 && rightTax === 10) {
            angle = 10;  // 右倾
        } else if (leftTax === 30 && rightTax === 10) {
            angle = -6;  // 混乱失衡
        }

        // 应用旋转到横梁和指针
        movableGroup.setAttribute('transform', `rotate(${angle}, ${centerX}, ${centerY})`);

        // 计算左右吊点在旋转后的实际坐标，以保持托盘垂直向下
        const rad = (angle * Math.PI) / 180;
        const leftX = centerX - armLength * Math.cos(rad);
        const leftY = centerY - armLength * Math.sin(rad);
        const rightX = centerX + armLength * Math.cos(rad);
        const rightY = centerY + armLength * Math.sin(rad);

        // 移动托盘
        leftPanGroup.setAttribute('transform', `translate(${leftX}, ${leftY})`);
        rightPanGroup.setAttribute('transform', `translate(${rightX}, ${rightY})`);

        // 更新 UI 样式与文本
        updateUI(angle);
    }

    // 更新文本与卡片颜色
    function updateUI(angle) {
        // 1. 按钮高亮切换
        if (leftTax === 9) {
            btnLeftLow.className = 'btn active-low';
            btnLeftHigh.className = 'btn';
        } else {
            btnLeftLow.className = 'btn';
            btnLeftHigh.className = 'btn active-high';
        }

        if (rightTax === 50) {
            btnRightLow.className = 'btn';
            btnRightHigh.className = 'btn active-high';
        } else {
            btnRightLow.className = 'btn active-low';
            btnRightHigh.className = 'btn';
        }

        // 2. 左侧卡片更新 (百姓生活)
        if (leftTax === 9) {
            leftStatusCard.style.borderColor = 'var(--success-color)';
            leftStatusTitle.innerHTML = '🟢 百姓生活：轻松';
            leftStatusTitle.style.color = 'var(--success-color)';
            leftStatusDesc.innerHTML = '<b>税率 9% (低)</b>：粮食是生存之本。低税率保障了人人都能买得起、吃得饱，基本生活有保障，社会安稳！';
        } else {
            leftStatusCard.style.borderColor = 'var(--warning-color)';
            leftStatusTitle.innerHTML = '🔴 百姓生活：沉重';
            leftStatusTitle.style.color = 'var(--warning-color)';
            leftStatusDesc.innerHTML = '<b>税率 30% (高)</b>：如果粮食税率过高，会导致物价飞涨，普通家庭尤其是低收入群体的生活压力会成倍增加！';
        }

        // 3. 右侧卡片更新 (社会引导)
        if (rightTax === 50) {
            rightStatusCard.style.borderColor = 'var(--success-color)';
            rightStatusTitle.innerHTML = '🟢 社会引导：积极';
            rightStatusTitle.style.color = 'var(--success-color)';
            rightStatusDesc.innerHTML = '<b>税率 50% (高)</b>：对烟草等有害健康或奢侈品征收高税，能有效抑制过度消费，同时为国家建设积累资金。';
        } else {
            rightStatusCard.style.borderColor = 'var(--warning-color)';
            rightStatusTitle.innerHTML = '🔴 社会引导：放任';
            rightStatusTitle.style.color = 'var(--warning-color)';
            rightStatusDesc.innerHTML = '<b>税率 10% (低)</b>：税率过低会导致烟草等商品价格便宜，可能引发青少年吸烟率上升，增加社会公共医疗负担。';
        }

        // 4. 整体和谐状态与引导语
        if (leftTax === 9 && rightTax === 50) {
            harmonyGlow.style.display = 'block';
            guidanceText.innerHTML = '<strong>✨ 达成完美平衡！</strong> <b>“保民生，调贫富”</b>。对生活必需品实行低税率，对限制消费品实行高税率。这正是国家制定税率的智慧与温度！';
            guidanceText.style.backgroundColor = '#e8f8f5';
            guidanceText.style.borderLeftColor = 'var(--success-color)';
        } else {
            harmonyGlow.style.display = 'none';
            guidanceText.style.backgroundColor = '#ebf5fb';
            guidanceText.style.borderLeftColor = '#3498db';

            if (leftTax === 30 && rightTax === 50) {
                guidanceText.innerHTML = '<strong>⚠️ 天平向左倾斜：</strong>虽然限制了有害消费，但<b>基本民生税率过高</b>，百姓生活吃力。请试着降低粮食税率。';
            } else if (leftTax === 9 && rightTax === 10) {
                guidanceText.innerHTML = '<strong>⚠️ 天平向右倾斜：</strong>虽然百姓生活轻松，但<b>烟草税率过低</b>，不利于国民健康和环境保护。请试着调高烟草税率。';
            } else {
                guidanceText.innerHTML = '<strong>❌ 双重失衡状态：</strong>民生负担重，且社会不良消费得不到抑制。请重新调整，寻找最合理的国家治理方案！';
                guidanceText.style.backgroundColor = '#fdedec';
                guidanceText.style.borderLeftColor = 'var(--warning-color)';
            }
        }
    }

    // 事件监听器绑定
    btnLeftLow.addEventListener('click', () => {
        leftTax = 9;
        updatePhysicalScale();
    });

    btnLeftHigh.addEventListener('click', () => {
        leftTax = 30;
        updatePhysicalScale();
    });

    btnRightLow.addEventListener('click', () => {
        rightTax = 10;
        updatePhysicalScale();
    });

    btnRightHigh.addEventListener('click', () => {
        rightTax = 50;
        updatePhysicalScale();
    });

    // 初始化运行
    updatePhysicalScale();
</script>

