<script>
    document.addEventListener('DOMContentLoaded', () => {
        const slider = document.getElementById('step-slider');
        const btnPrev = document.getElementById('btn-prev');
        const btnNext = document.getElementById('btn-next');
        const btnPlay = document.getElementById('btn-play');

        const labels = [
            document.getElementById('label-1'),
            document.getElementById('label-2'),
            document.getElementById('label-3')
        ];

        // 节点定义
        const nodes = {
            private: [
                document.getElementById('node-pri-1'),
                document.getElementById('node-pri-2'),
                document.getElementById('node-pri-3')
            ],
            public: [
                document.getElementById('node-pub-1'),
                document.getElementById('node-pub-2'),
                document.getElementById('node-pub-3')
            ]
        };

        const arrows = {
            private: [
                document.getElementById('arrow-pri-1'),
                document.getElementById('arrow-pri-2')
            ],
            public: [
                document.getElementById('arrow-pub-1'),
                document.getElementById('arrow-pub-2')
            ]
        };

        let currentStep = 1;
        let playInterval = null;

        // 更新视图状态
        function updateVisualization(step) {
            currentStep = step;
            slider.value = step;

            // 更新控制按钮状态
            btnPrev.disabled = (step === 1);
            btnNext.disabled = (step === 3);

            // 更新标签高亮
            labels.forEach((label, index) => {
                if (index + 1 === step) {
                    label.classList.add('active');
                } else {
                    label.classList.remove('active');
                }
            });

            // 更新流程节点和箭头的激活状态
            for (let i = 0; i < 3; i++) {
                // 私人
                if (i + 1 <= step) {
                    nodes.private[i].classList.add('active');
                } else {
                    nodes.private[i].classList.remove('active');
                }
                // 箭头
                if (i < 2) {
                    if (i + 1 < step) {
                        arrows.private[i].classList.add('active');
                    } else {
                        arrows.private[i].classList.remove('active');
                    }
                }

                // 公共
                if (i + 1 <= step) {
                    nodes.public[i].classList.add('active');
                } else {
                    nodes.public[i].classList.remove('active');
                }
                // 箭头
                if (i < 2) {
                    if (i + 1 < step) {
                        arrows.public[i].classList.add('active');
                    } else {
                        arrows.public[i].classList.remove('active');
                    }
                }
            }

            // 触发金币流动动画
            triggerCoinAnimation(step);
        }

        // 模拟金币流动动画
        function triggerCoinAnimation(step) {
            // 清除旧的粒子
            const container = document.getElementById('particle-container');
            container.innerHTML = '';

