    <!-- 主体 -->
    <div class="main-content">
      <!-- 左侧：SVG 动画交互区 -->
      <div class="visualizer-panel">
        <svg class="gauge-svg" viewBox="0 0 400 450">
          <!-- 背景网格与刻度线 -->
          <g id="grid">
            <!-- 刻度线 (0 到 8000，每1000一格) -->
            <!-- Y 轴映射：0元 -> Y=400, 8000元 -> Y=80 -->
