            <text x="50" y="400" class="axis-label">0元</text>

            <line x1="80" y1="360" x2="280" y2="360" stroke="#e2e8f0" stroke-width="1" />
            <text x="50" y="360" class="axis-label">1000元</text>

            <line x1="80" y1="320" x2="280" y2="320" stroke="#e2e8f0" stroke-width="1" />
            <text x="50" y="320" class="axis-label">2000元</text>

            <line x1="80" y1="280" x2="280" y2="280" stroke="#e2e8f0" stroke-width="1" />
            <text x="50" y="280" class="axis-label">3000元</text>

            <line x1="80" y1="240" x2="280" y2="240" stroke="#e2e8f0" stroke-width="1" />
            <text x="50" y="240" class="axis-label">4000元</text>

            <line x1="80" y1="160" x2="280" y2="160" stroke="#e2e8f0" stroke-width="1" />
