          </g>

          <!-- 柱状容器外框 -->
          <rect x="120" y="70" width="120" height="340" fill="none" stroke="#718096" stroke-width="3" rx="5" />

          <!-- 免税部分水柱 (蓝色) -->
          <rect id="free-water" x="122" y="400" width="116" height="0" fill="#3182ce" opacity="0.85" />

          <!-- 纳税部分水柱 (橙色) -->
          <rect id="tax-water" x="122" y="200" width="116" height="0" fill="#dd6b20" opacity="0.9" />

