            <rect x="125" y="205" width="110" height="25" fill="#f0fff4" rx="4" opacity="0.8"/>
            <text x="180" y="222" fill="#2f855a" font-size="11" font-weight="bold" text-anchor="middle">5000元以下免税区</text>
          </g>

          <!-- 动态高度指示线与文本 -->
