          <div class="preset-container">
            <button class="btn active" id="btn-4800">陈阿姨 (4800元)</button>
            <button class="btn" id="btn-5000">起征点 (5000元)</button>
            <button class="btn" id="btn-6500">假设 (6500元)</button>
