  <script>
    const slider = document.getElementById('salary-slider');
    const salaryDisplay = document.getElementById('salary-display');
    const freeWater = document.getElementById('free-water');
    const taxWater = document.getElementById('tax-water');
    const indicatorLine = document.getElementById('indicator-line');
    const indicatorBg = document.getElementById('indicator-bg');
    const indicatorText = document.getElementById('indicator-text');

    const resTotal = document.getElementById('res-total');
    const resTaxable = document.getElementById('res-taxable');
    const resTax = document.getElementById('res-tax');
    const analysisOutput = document.getElementById('analysis-output');

    const btn4800 = document.getElementById('btn-4800');
    const btn5000 = document.getElementById('btn-5000');
    const btn6500 = document.getElementById('btn-6500');

    const THRESHOLD = 5000;
    const TAX_RATE = 0.03;

    // Y轴映射关系：0元 -> Y=400, 8000元 -> Y=80 (总高度320px)
    function getScaleY(value) {
      const minY = 400;
      const maxY = 80;
      const maxVal = 8000;
      return minY - (value / maxVal) * (minY - maxY);
    }

    function updateVisualization(salary) {
      // 1. 更新数值显示
      salaryDisplay.textContent = salary + ' 元';
      resTotal.textContent = salary + ' 元';

      const yZero = getScaleY(0);
      const yThreshold = getScaleY(THRESHOLD); // Y = 200
      const ySalary = getScaleY(salary);

      // 2. 计算纳税逻辑
      let taxableIncome = 0;
      let tax = 0;

      if (salary <= THRESHOLD) {
        // 未超起征点：全部高度为蓝色，无橙色
        const height = yZero - ySalary;
        freeWater.setAttribute('y', ySalary);
        freeWater.setAttribute('height', height);

        taxWater.setAttribute('height', 0);
        taxWater.setAttribute('y', yThreshold);

        taxableIncome = 0;
        tax = 0;

        // 更新辨析框
        analysisOutput.className = 'analysis-box correct';
        analysisOutput.innerHTML = `
          <strong>💡 课堂辨析：</strong><br>
          陈阿姨的工资 <strong>${salary}元</strong> 没有超过起征点 <strong>5000元</strong>。<br>
          所以，陈阿姨<strong>不需要缴纳</strong>个人所得税！<br>
          <span style="font-weight:bold; color:var(--success-color);">同学的列式 4800 × 3% 是错误的。</span>
        `;
      } else {
        // 超过起征点：5000以下为蓝色，5000以上为橙色
        freeWater.setAttribute('y', yThreshold);
        freeWater.setAttribute('height', yZero - yThreshold); // 刚好填满免税区

        const taxHeight = yThreshold - ySalary;
        taxWater.setAttribute('y', ySalary);
        taxWater.setAttribute('height', taxHeight);

        taxableIncome = salary - THRESHOLD;
        tax = taxableIncome * TAX_RATE;

        // 更新辨析框
        analysisOutput.className = 'analysis-box wrong';
        analysisOutput.innerHTML = `
          <strong>💡 课堂辨析：</strong><br>
          工资 <strong>${salary}元</strong> 已越过安全闸门！<br>
          只有超出起征点的部分 <strong>${taxableIncome}元</strong> 才需要按 3% 纳税。<br>
          正确列式：<code>(${salary} - 5000) × 3% = ${tax.toFixed(1)}元</code>
        `;
      }

      // 3. 更新计算卡片
      resTaxable.textContent = taxableIncome + ' 元';
      resTax.textContent = tax.toFixed(2) + ' 元';

      // 4. 更新动态指示线
      indicatorLine.setAttribute('y1', ySalary);
      indicatorLine.setAttribute('y2', ySalary);
      indicatorBg.setAttribute('y', ySalary - 11);
      indicatorText.setAttribute('y', ySalary + 5);
      indicatorText.textContent = salary + '元';
    }

    // 滑块事件监听
    slider.addEventListener('input', (e) => {
      const val = parseInt(e.target.value);
      updateVisualization(val);
      updateActiveButton(val);
    });

    // 按钮高亮切换
