<script>
    // 获取DOM元素
    const btnCalc = document.getElementById('btnCalc');
    const btnConnect = document.getElementById('btnConnect');
    const btnReset = document.getElementById('btnReset');

    const fuelCard = document.getElementById('fuelCard');
    const evCard = document.getElementById('evCard');

    const fuelTaxBadge = document.getElementById('fuelTaxBadge');
    const evTaxBadge = document.getElementById('evTaxBadge');

    const fuelTaxText = document.getElementById('fuelTaxText');
    const fuelTotalText = document.getElementById('fuelTotalText');
    const evTaxText = document.getElementById('evTaxText');
    const evTotalText = document.getElementById('evTotalText');

    const smokeContainer = document.getElementById('smokeContainer');
    const leafContainer = document.getElementById('leafContainer');
    const policyPanel = document.getElementById('policyPanel');

    let smokeInterval = null;
    let leafInterval = null;

    // 1. 计算总花费
    btnCalc.addEventListener('click', () => {
        // 激活卡片高亮
        fuelCard.classList.add('active-fuel');
        evCard.classList.add('active-ev');

        // 落下税金砖/免税牌
        fuelTaxBadge.classList.add('drop');
        evTaxBadge.classList.add('drop');

        // 延迟更新价格文字，配合动画节奏
        setTimeout(() => {
            fuelTaxText.innerHTML = '<span style="color:var(--fuel-color); font-weight:bold;">+1.5 万元</span> (15 × 10%)';
            fuelTotalText.innerText = '16.5 万元';

            evTaxText.innerHTML = '<span style="color:var(--ev-color); font-weight:bold;">+0 元</span> (免税)';
            evTotalText.innerText = '15.0 万元';
        }, 600);

        // 启动环境效果动画
        startSmoke();
        startLeaves();

        // 激活下一步按钮
        btnConnect.removeAttribute('disabled');
        btnCalc.setAttribute('disabled', 'true');
    });

    // 2. 政策连线分析
    btnConnect.addEventListener('click', () => {
        policyPanel.classList.add('active');

        // 依次高亮因果链节点
        const nodes = ['node1', 'node2', 'node3', 'node4'];
        nodes.forEach((id, index) => {
            setTimeout(() => {
                document.getElementById(id).classList.add('highlight');
            }, index * 600);
        });
    });

    // 3. 重置
    btnReset.addEventListener('click', () => {
        // 停止动画
        stopSmoke();
        stopLeaves();

        // 恢复初始状态
        fuelCard.classList.remove('active-fuel');
        evCard.classList.remove('active-ev');

        fuelTaxBadge.classList.remove('drop');
        evTaxBadge.classList.remove('drop');

        fuelTaxText.innerText = '待计算';
        fuelTotalText.innerText = '15.0 万元';
        evTaxText.innerText = '待计算';
        evTotalText.innerText = '15.0 万元';

        policyPanel.classList.remove('active');
        const nodes = ['node1', 'node2', 'node3', 'node4'];
        nodes.forEach(id => {
            document.getElementById(id).classList.remove('highlight');
        });

        btnCalc.removeAttribute('disabled');
        btnConnect.setAttribute('disabled', 'true');
    });

    // 产生尾气动画
    function startSmoke() {
        if (smokeInterval) clearInterval(smokeInterval);
        smokeInterval = setInterval(() => {
