      const windowWidth = window.innerWidth;
      const windowHeight = window.innerHeight;
      const targetWidth = 800;
      const targetHeight = 600;

      const scaleX = windowWidth / targetWidth;
      const scaleY = windowHeight / targetHeight;
      const scale = Math.min(scaleX, scaleY, 1.5); // 限制最大缩放倍数

      container.style.transform = `scale(${scale})`;

      // 居中定位
      const left = (windowWidth - targetWidth * scale) / 2;
      const top = (windowHeight - targetHeight * scale) / 2;
      container.style.left = `${left}px`;
      container.style.top = `${top}px`;
    }

    window.addEventListener('resize', resizeContainer);
    window.addEventListener('DOMContentLoaded', resizeContainer);

    // 交互逻辑状态管理
    let currentState = 0; // 0: 初始, 1: 比纳税额, 2: 看营业额, 3: 算税率

    const btnStep1 = document.getElementById('btn-step1');
