      const rad = angle * Math.PI / 180;
      const cx = 400, cy = 100, r = 200;

      // 计算旋转后左右悬挂点的实际坐标
      const lx = cx - r * Math.cos(rad);
      const ly = cy - r * Math.sin(rad);
      const rx = cx + r * Math.cos(rad);
      const ry = cy + r * Math.sin(rad);

      // 旋转横梁
      document.getElementById('scale-beam').style.transform = `rotate(${angle}deg)`;

      // 平移吊盘，使其保持垂直向下悬挂
      document.getElementById('left-pan').style.transform = `translate(${lx - 200}px, ${ly - 100}px)`;
      document.getElementById('right-pan').style.transform = `translate(${rx - 600}px, ${ry - 100}px)`;
    }

    // 初始化天平
