      instruction.style.borderLeftColor = "#2ed573";

      // 5. 按钮状态
      btnStep3.disabled = true;
      btnStep3.classList.remove('pulse');
    });

    // 重置按钮
    btnReset.addEventListener('click', () => {
      currentState = 0;

      // 1. 重置天平
      setScaleAngle(0);
