      document.getElementById('right-weight-text').textContent = "600元";
      document.getElementById('left-weight').querySelector('rect').setAttribute('height', '40');
      document.getElementById('left-weight').querySelector('rect').setAttribute('y', '140');
      document.getElementById('left-weight-text').setAttribute('y', '165');
