      const superRev = document.getElementById('val-super-rev');
      const restRate = document.getElementById('val-rest-rate');
      const superRate = document.getElementById('val-super-rate');

      restRev.textContent = "????? 元";
      restRev.className = "data-value secret";
      superRev.textContent = "????? 元";
      superRev.className = "data-value secret";

      restRate.textContent = "?? %";
      restRate.className = "data-value secret";
      superRate.textContent = "?? %";
