    const resetBtn = document.getElementById('resetBtn');
    const instructionText = document.getElementById('instructionText');

    const turnoverRest = document.getElementById('turnoverRest');
    const turnoverSuper = document.getElementById('turnoverSuper');

    const coinRest = document.getElementById('coinRest');
    const coinSuper = document.getElementById('coinSuper');

    const dropRest = document.getElementById('dropRest');
    const dropSuper = document.getElementById('dropSuper');

    const tagRest = document.getElementById('tagRest');
    const tagSuper = document.getElementById('tagSuper');

    // 初始坐标记录，用于重置
    const initialPositions = {
