      // 展开超市营业额
      turnoverSuper.classList.add('revealed');
      turnoverSuper.innerHTML = `
        <div class="turnover-label">营业额</div>
        <div class="turnover-value">12000 元</div>
      `;

      // 解锁硬币
      coinRest.classList.remove('locked');
      coinSuper.classList.remove('locked');

      // 更新引导语
      instructionText.textContent = '第二步：请将代表“纳税额”的金色卡片，拖入对应店铺的“营业额”大箱子里。';

