    // 实现拖拽逻辑 (兼容鼠标与触摸屏)
    setupDragAndDrop(coinRest, dropRest, 'restaurant');
    setupDragAndDrop(coinSuper, dropSuper, 'supermarket');

    function setupDragAndDrop(coin, dropZone, type) {
      let active = false;
      let currentX;
      let currentY;
      let initialX;
      let initialY;
      let xOffset = 0;
      let yOffset = 0;

      coin.addEventListener('pointerdown', dragStart);

      function dragStart(e) {
        if (coin.classList.contains('locked')) return;

        // 记录初始点击位置
        initialX = e.clientX - xOffset;
        initialY = e.clientY - yOffset;

        if (e.target === coin || coin.contains(e.target)) {
          active = true;
          coin.style.zIndex = '1000';
          coin.style.transition = 'none';
          coin.setPointerCapture(e.pointerId);

          // 拖拽开始时，高亮对应的目标区域
          dropZone.classList.add('active-hover');

          coin.addEventListener('pointermove', drag);
          coin.addEventListener('pointerup', dragEnd);
