        if (type === 'restaurant') {
          label.innerHTML = `<strong style="color: #2f855a; font-size: 18px;">餐馆：1500元 ↔ 30000元</strong>`;
        } else {
          label.innerHTML = `<strong style="color: #2f855a; font-size: 18px;">超市：600元 ↔ 12000元</strong>`;
        }

        tag.style.display = 'block';

        successCount++;
        checkCompletion();
      }
    }

    // 检查是否全部完成
    function checkCompletion() {
      if (successCount === 2) {
        instructionText.style.backgroundColor = '#c6f6d5';
        instructionText.style.borderColor = '#9ae6b4';
        instructionText.style.color = '#22543d';
        instructionText.innerHTML = '<strong>配对成功！</strong> 观察两组对应关系，我们要比较纳税负担，应该把“纳税额”和“营业额”放在一起比。';
      }
    }

    // 重置所有状态
    resetBtn.addEventListener('click', () => {
      isRevealed = false;
      successCount = 0;

      // 重置控制按钮
      revealBtn.classList.remove('disabled');
      revealBtn.disabled = false;

      // 重置引导语
      instructionText.style.backgroundColor = '#ebf8ff';
      instructionText.style.borderColor = '#bee3f8';
      instructionText.style.color = '#4a5568';
      instructionText.textContent = '第一步：请点击下方按钮，展开两家店铺的营业额。';

      // 重置营业额展示
