      turnoverRest.innerHTML = `<span class="turnover-placeholder">营业额已隐藏</span>`;
      turnoverSuper.classList.remove('revealed');
      turnoverSuper.innerHTML = `<span class="turnover-placeholder">营业额已隐藏</span>`;

