  <script>
    // 状态管理
    const state = {
      slots: [null, null, null], // [number, operator, number]
      correctFormula: ['1500', '÷', '30000']
    };

    // DOM 元素
    const slotsDOM = document.querySelectorAll('.slot');
    const cardsDOM = document.querySelectorAll('.card');
    const equationArea = document.getElementById('equation-area');
    const resultMessage = document.getElementById('result-message');
    const btnReset = document.getElementById('btn-reset');
    const btnSimplify = document.getElementById('btn-simplify');
    const simplificationSection = document.getElementById('simplification-section');

    // 音效合成器 (Web Audio API)
    function playSound(type) {
      try {
        const ctx = new (window.AudioContext || window.webkitAudioContext)();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);

        if (type === 'success') {
          osc.type = 'sine';
          osc.frequency.setValueAtTime(523.25, ctx.currentTime); // C5
          osc.frequency.setValueAtTime(659.25, ctx.currentTime + 0.12); // E5
          osc.frequency.setValueAtTime(783.99, ctx.currentTime + 0.24); // G5
          gain.gain.setValueAtTime(0.15, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);
          osc.start();
          osc.stop(ctx.currentTime + 0.5);
        } else if (type === 'error') {
          osc.type = 'sawtooth';
          osc.frequency.setValueAtTime(150, ctx.currentTime);
          osc.frequency.linearRampToValueAtTime(100, ctx.currentTime + 0.3);
          gain.gain.setValueAtTime(0.15, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.3);
          osc.start();
          osc.stop(ctx.currentTime + 0.3);
        } else if (type === 'click') {
          osc.type = 'triangle';
          osc.frequency.setValueAtTime(600, ctx.currentTime);
          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
          osc.start();
          osc.stop(ctx.currentTime + 0.1);
        }
      } catch (e) {
        // 忽略不支持 Web Audio API 的浏览器
      }
    }

    // 初始化与事件绑定
    function init() {
      setupDragAndDrop();
      setupClickInteraction();

      btnReset.addEventListener('click', resetWorkspace);
      btnSimplify.addEventListener('click', toggleSimplification);
    }

    // 交互逻辑：点击卡片自动填入
    function setupClickInteraction() {
      cardsDOM.forEach(card => {
        card.addEventListener('click', () => {
          if (card.classList.contains('used')) return;

          const val = card.dataset.value;
          const isOperator = card.classList.contains('operator-card');

          let targetSlotIndex = -1;
          if (isOperator) {
            if (!state.slots[1]) targetSlotIndex = 1;
          } else {
            if (!state.slots[0]) targetSlotIndex = 0;
            else if (!state.slots[2]) targetSlotIndex = 2;
          }

          if (targetSlotIndex !== -1) {
            playSound('click');
            fillSlot(targetSlotIndex, val, card.id);
          }
        });
      });

      // 点击插槽取回卡片
      slotsDOM.forEach(slot => {
        slot.addEventListener('click', () => {
          const index = parseInt(slot.dataset.slotIndex);
          if (state.slots[index]) {
            playSound('click');
            clearSlot(index);
          }
        });
      });
    }

    // 交互逻辑：拖拽
    let draggedCardId = null;

    function setupDragAndDrop() {
      cardsDOM.forEach(card => {
        card.addEventListener('dragstart', (e) => {
          draggedCardId = card.id;
          card.classList.add('dragging');
          e.dataTransfer.setData('text/plain', card.id);
        });

        card.addEventListener('dragend', () => {
          card.classList.remove('dragging');
        });
      });

      slotsDOM.forEach(slot => {
        slot.addEventListener('dragover', (e) => {
          e.preventDefault();
          const cardType = document.getElementById(draggedCardId).classList.contains('operator-card') ? 'operator' : 'number';
          if (slot.dataset.type === cardType) {
            slot.classList.add('active-hover');
          }
        });

        slot.addEventListener('dragleave', () => {
          slot.classList.remove('active-hover');
        });

        slot.addEventListener('drop', (e) => {
          e.preventDefault();
          slot.classList.remove('active-hover');
          const cardId = e.dataTransfer.getData('text/plain');
          const card = document.getElementById(cardId);
          const cardType = card.classList.contains('operator-card') ? 'operator' : 'number';
          const slotIndex = parseInt(slot.dataset.slotIndex);

          if (slot.dataset.type === cardType) {
            // 如果插槽已有卡片，先清除
            if (state.slots[slotIndex]) {
              clearSlot(slotIndex);
            }
            playSound('click');
            fillSlot(slotIndex, card.dataset.value, cardId);
          }
        });
      });
    }

    // 填充插槽
    function fillSlot(slotIndex, value, cardId) {
      state.slots[slotIndex] = value;

      const slot = slotsDOM[slotIndex];
      slot.textContent = value;
      slot.classList.add('filled');
      slot.dataset.cardId = cardId;

      // 标记原卡片为已使用
      document.getElementById(cardId).classList.add('used');

      checkFormula();
    }

    // 清除插槽
    function clearSlot(slotIndex) {
      const slot = slotsDOM[slotIndex];
      const cardId = slot.dataset.cardId;

      if (cardId) {
        document.getElementById(cardId).classList.remove('used');
      }

      state.slots[slotIndex] = null;
      slot.textContent = '';
      slot.classList.remove('filled');
      delete slot.dataset.cardId;

      checkFormula();
    }

    // 检查算式正确性
    function checkFormula() {
      // 隐藏化简过程
      simplificationSection.classList.add('hidden');
      btnSimplify.classList.add('hidden');
      equationArea.classList.remove('correct', 'wrong');
      resultMessage.textContent = '';
      resultMessage.className = 'result-message';

      // 检查是否填满
      const isFilled = state.slots.every(val => val !== null);
      if (!isFilled) return;

      // 验证算式
      const isCorrect = state.slots[0] === state.correctFormula[0] && 
                        state.slots[1] === state.correctFormula[1] && 
                        state.slots[2] === state.correctFormula[2];

      if (isCorrect) {
        equationArea.classList.add('correct');
        resultMessage.textContent = '🎉 列式完全正确！1500 ÷ 30000 表示求 1500 是 30000 的几分之几。';
        resultMessage.classList.add('success');
        btnSimplify.classList.remove('hidden');
        playSound('success');
      } else {
        equationArea.classList.add('wrong');
        resultMessage.classList.add('error');
        playSound('error');

        // 针对性教学引导
        if (state.slots[1] !== '÷') {
          resultMessage.textContent = '❌ 提示：求一个数是另一个数的几分之几，应该用什么运算符号呢？';
        } else if (state.slots[0] === '30000' && state.slots[2] === '1500') {
          resultMessage.textContent = '❌ 提示：除数和被除数位置反了哦！是用“比较量”除以“标准量”。';
        } else {
          resultMessage.textContent = '❌ 列式不正确，再想一想！求一个数是另一个数的几分之几，用除法计算。';
        }
      }
    }

    // 重置工作区
    function resetWorkspace() {
      playSound('click');
      slotsDOM.forEach((_, index) => clearSlot(index));
    }

    // 切换化简过程显示
    function toggleSimplification() {
      playSound('click');
      simplificationSection.classList.toggle('hidden');
      if (!simplificationSection.classList.contains('hidden')) {
        simplificationSection.scrollIntoView({ behavior: 'smooth' });
      }
    }

    // 启动
    init();
  </script>
</body>
