        zero1Opacity: 0.15, // 淡化无意义的0
        zero2Opacity: 0.15,
        percentShow: true, // 展现百分号
        strike1Width: '40px', // 划线消除
        strike2Width: '40px',
        arrow1Active: true,
        arrow2Active: true,
        desc: "最后：去掉整数前面无意义的“0”，省去末尾的小数点，并添上红色的百分号“%”。最终得到 5%！"
      }
    ];

    let currentStateIndex = 0;
    let autoPlayInterval = null;

    // DOM 元素获取
    const digitDot = document.getElementById('digitDot');
    const digit01 = document.getElementById('digit01');
    const digit02 = document.getElementById('digit02');
    const digitPercent = document.getElementById('digitPercent');
    const strike1 = document.getElementById('strike1');
    const strike2 = document.getElementById('strike2');
    const jump1 = document.getElementById('jump1');
    const jump2 = document.getElementById('jump2');
    const jumpText1 = document.getElementById('jumpText1');
    const jumpText2 = document.getElementById('jumpText2');
    const explanation = document.getElementById('explanation');

    const btnPrev = document.getElementById('btnPrev');
    const btnNext = document.getElementById('btnNext');
    const btnReset = document.getElementById('btnReset');
    const btnAuto = document.getElementById('btnAuto');

    const stepNodes = document.querySelectorAll('.step-node');
    const lineProgress = document.getElementById('lineProgress');

    // 渲染状态
    function renderState(index) {
      const state = states[index];

      // 更新数字位置与状态
      digitDot.style.left = state.dotLeft;
      digitDot.style.opacity = state.dotOpacity;
      digit01.style.opacity = state.zero1Opacity;
      digit02.style.opacity = state.zero2Opacity;

      if (state.percentShow) {
        digitPercent.classList.add('show');
      } else {
        digitPercent.classList.remove('show');
      }

      // 划线消除
      strike1.style.width = state.strike1Width;
      strike2.style.width = state.strike2Width;

      // SVG 弧线与文字
      if (state.arrow1Active) {
        jump1.classList.add('active');
        jumpText1.classList.add('active');
      } else {
        jump1.classList.remove('active');
        jumpText1.classList.remove('active');
      }

      if (state.arrow2Active) {
        jump2.classList.add('active');
        jumpText2.classList.add('active');
      } else {
        jump2.classList.remove('active');
        jumpText2.classList.remove('active');
      }

      // 文字说明
      explanation.textContent = state.desc;

      // 步骤指示器更新
      stepNodes.forEach((node, idx) => {
        node.className = 'step-node';
        if (idx < index) {
          node.classList.add('completed');
          node.innerHTML = '✓';
        } else if (idx === index) {
          node.classList.add('active');
          node.innerHTML = idx === 0 ? '始' : idx === 3 ? '终' : idx;
        } else {
          node.innerHTML = idx === 3 ? '终' : idx;
        }
      });

      // 进度条比例
      const progressWidths = [0, 33.3, 66.6, 100];
      lineProgress.style.width = `${progressWidths[index]}%`;

      // 按钮状态控制
      btnPrev.disabled = index === 0;
      btnNext.disabled = index === states.length - 1;

      if (index === states.length - 1) {
        btnNext.textContent = '完成';
        btnNext.classList.replace('btn-primary', 'btn-accent');
      } else {
        btnNext.textContent = '下一步';
        btnNext.classList.replace('btn-accent', 'btn-primary');
      }
    }

    // 交互事件绑定
    function goToStep(index) {
      currentStateIndex = index;
      renderState(currentStateIndex);
      stopAutoPlay();
    }

    function nextStep() {
      if (currentStateIndex < states.length - 1) {
        currentStateIndex++;
        renderState(currentStateIndex);
      } else {
        stopAutoPlay();
      }
    }

    function prevStep() {
      if (currentStateIndex > 0) {
        currentStateIndex--;
        renderState(currentStateIndex);
      }
      stopAutoPlay();
    }

    function resetDemo() {
      goToStep(0);
    }

    function toggleAutoPlay() {
      if (autoPlayInterval) {
        stopAutoPlay();
      } else {
        if (currentStateIndex === states.length - 1) {
          currentStateIndex = 0;
        }
        renderState(currentStateIndex);
        btnAuto.textContent = '暂停演示';
        btnAuto.classList.replace('btn-accent', 'btn-secondary');
        autoPlayInterval = setInterval(() => {
          if (currentStateIndex < states.length - 1) {
            nextStep();
          } else {
            stopAutoPlay();
          }
        }, 2500);
      }
    }

    function stopAutoPlay() {
      if (autoPlayInterval) {
        clearInterval(autoPlayInterval);
        autoPlayInterval = null;
        btnAuto.textContent = '自动演示';
        btnAuto.classList.replace('btn-secondary', 'btn-accent');
      }
    }

    // 按钮事件监听
    btnNext.addEventListener('click', nextStep);
    btnPrev.addEventListener('click', prevStep);
    btnReset.addEventListener('click', resetDemo);
    btnAuto.addEventListener('click', toggleAutoPlay);

    // 步骤节点点击事件
    stepNodes.forEach((node) => {
      node.addEventListener('click', () => {
        const step = parseInt(node.getAttribute('data-step'));
        goToStep(step);
      });
    });

    // 初始化渲染
    renderState(0);
  </script>
