<body>

  <div class="app-container">
    <!-- 头部 -->
    <div class="header">
      <h1>百分数化成小数</h1>
      <p>拖动滑块，观察百分数在数轴和百格图上对应的小数变化</p>
    </div>

    <!-- 主交互区 -->
    <div class="main-content">
      <!-- 左侧控制面板 -->
      <div class="left-panel">
        <!-- 数轴 -->
        <div class="axis-container">
          <svg id="number-line" viewBox="0 0 550 120" width="100%">
            <!-- 动态生成 -->
          </svg>
        </div>

        <!-- 滑块 -->
        <div class="slider-wrapper">
          <input type="range" id="percent-slider" class="custom-slider" min="0" max="10" value="0" step="1">
        </div>

        <!-- 转换结果展示 -->
        <div id="display-box" class="display-box">
          <div class="display-item">
            <div class="display-label">百分数</div>
            <div id="percent-val" class="display-value">0%</div>
          </div>
          <div class="arrow-icon">➔</div>
          <div class="display-item">
            <div class="display-label">小数</div>
            <div id="decimal-val" class="display-value">0.00</div>
          </div>
        </div>
      </div>

      <!-- 右侧百格图 -->
      <div class="right-panel">
        <div class="grid-title">百格图 (整个大正方形为 1)</div>
        <div id="grid-100" class="grid-container">
          <!-- 动态生成100个格子 -->
        </div>
        <div class="grid-info">
          阴影部分占整个图的：<strong id="grid-count" style="color: var(--primary-color);">0</strong> / 100
        </div>
      </div>
    </div>

    <!-- 底部控制栏 -->
    <div class="footer-bar">
      <div class="guide-text">
        <span id="guide-dot"></span>
        <span id="guide-msg">请拖动滑块寻找 5% 吧！</span>
      </div>
      <button id="btn-compare" class="btn btn-warning">⚠️ 5% 是 0.5 吗？</button>
    </div>

    <!-- 对比弹窗 -->
    <div id="compare-modal" class="modal-overlay">
      <div class="modal-card">
        <div class="modal-header">
          <div class="modal-title">⚠️ 概念辨析：0.5 还是 0.05？</div>
        </div>

        <div class="alert-banner">
          <strong>红色警示：</strong>0.5 是 50% 哦！5% 只有 5 个 0.01，所以是 0.05！
        </div>

        <div class="compare-container">
          <!-- 0.5 的情况 -->
          <div class="compare-box error-focus">
            <h3>0.5 (即 50%)</h3>
            <div id="grid-50" class="mini-grid"></div>
            <div class="compare-text" style="color: var(--danger-color);">50 个格子 (半张图)</div>
          </div>

          <!-- 0.05 的情况 -->
          <div class="compare-box correct-focus">
            <h3>0.05 (即 5%)</h3>
            <div id="grid-5" class="mini-grid"></div>
            <div class="compare-text" style="color: var(--success-color);">5 个格子 (极小部分)</div>
          </div>
        </div>

        <button id="btn-close" class="btn btn-close">我明白了，返回练习</button>
      </div>
    </div>
  </div>

  <script>
    document.addEventListener('DOMContentLoaded', () => {
      const slider = document.getElementById('percent-slider');
      const percentVal = document.getElementById('percent-val');
      const decimalVal = document.getElementById('decimal-val');
      const displayBox = document.getElementById('display-box');
      const grid100 = document.getElementById('grid-100');
      const gridCount = document.getElementById('grid-count');
      const guideDot = document.getElementById('guide-dot');
      const guideMsg = document.getElementById('guide-msg');
      const btnCompare = document.getElementById('btn-compare');
      const compareModal = document.getElementById('compare-modal');
      const btnClose = document.getElementById('btn-close');
      const svgLine = document.getElementById('number-line');

      // 初始化百格图
      function initGrid() {
        grid100.innerHTML = '';
        for (let i = 0; i < 100; i++) {
          const cell = document.createElement('div');
          cell.classList.add('grid-cell');
          grid100.appendChild(cell);
        }
      }

      // 初始化数轴 SVG
      function initSvgLine() {
        let html = `
          <!-- 主轴线 -->
          <line x1="30" y1="60" x2="520" y2="60" stroke="#bdc3c7" stroke-width="4" stroke-linecap="round" />
        `;

        // 刻度 0 到 10% (对应 0 到 0.10)
        for (let i = 0; i <= 10; i++) {
          const x = 30 + i * 49;
          html += `
            <!-- 刻度线 -->
            <line x1="${x}" y1="50" x2="${x}" y2="70" stroke="#7f8c8d" stroke-width="2" />
            <!-- 上方百分比标签 -->
            <text x="${x}" y="35" class="tick-label percent-label" data-idx="${i}">${i}%</text>
            <!-- 下方小数标签 -->
            <text x="${x}" y="95" class="tick-label decimal-label" data-idx="${i}">${(i/100).toFixed(2)}</text>
          `;
        }

        // 游标指针
        html += `
          <g id="pointer" transform="translate(30, 60)">
            <line x1="0" y1="-25" x2="0" y2="25" stroke="#3498db" stroke-width="2" stroke-dasharray="3,3" />
            <circle cx="0" cy="0" r="8" fill="#3498db" stroke="#fff" stroke-width="2" />
          </g>
        `;

        svgLine.innerHTML = html;
      }

      // 更新视图
      function updateView(val) {
        const percent = val;
        const decimal = (val / 100).toFixed(2);

        // 1. 更新文本
        percentVal.textContent = `${percent}%`;
        decimalVal.textContent = decimal;

        // 2. 更新数轴指针位置
        const pointer = document.getElementById('pointer');
        const targetX = 30 + val * 49;
        pointer.setAttribute('transform', `translate(${targetX}, 60)`);

        // 3. 更新数轴标签高亮
        document.querySelectorAll('.tick-label').forEach(el => {
          el.classList.remove('active-tick');
        });
        document.querySelectorAll(`[data-idx="${val}"]`).forEach(el => {
          el.classList.add('active-tick');
        });

        // 4. 更新百格图
        const cells = grid100.querySelectorAll('.grid-cell');
        cells.forEach((cell, idx) => {
          if (idx < val) {
            cell.className = 'grid-cell active';
            if (val === 5) {
              cell.classList.add('highlight-cell');
            }
          } else {
            cell.className = 'grid-cell';
          }
        });
        gridCount.textContent = val;

        // 5. 拦截 5% 核心目标
        if (val === 5) {
          displayBox.classList.add('highlight-target');
          percentVal.classList.add('highlight');
          decimalVal.classList.add('highlight');
          guideDot.style.backgroundColor = 'var(--success-color)';
          guideMsg.innerHTML = '✨ 完美！<strong>5% = 0.05</strong>。它只有5个0.01。';

          // 改变游标颜色为绿色
          pointer.querySelector('circle').setAttribute('fill', 'var(--success-color)');
          pointer.querySelector('line').setAttribute('stroke', 'var(--success-color)');
        } else {
          displayBox.classList.remove('highlight-target');
          percentVal.classList.remove('highlight');
          decimalVal.classList.remove('highlight');
          guideDot.style.backgroundColor = 'var(--accent-color)';
          guideMsg.textContent = '继续拖动，观察百分数与小数的对应关系';

          // 恢复游标颜色
          pointer.querySelector('circle').setAttribute('fill', 'var(--primary-color)');
          pointer.querySelector('line').setAttribute('stroke', 'var(--primary-color)');
        }
      }

      // 渲染对比弹窗中的微型百格图
      function renderMiniGrids() {
        const grid50 = document.getElementById('grid-50');
        const grid5 = document.getElementById('grid-5');

        grid50.innerHTML = '';
        grid5.innerHTML = '';

        for (let i = 0; i < 100; i++) {
          const cell50 = document.createElement('div');
          cell50.className = `mini-cell ${i < 50 ? 'active-red' : ''}`;
          grid50.appendChild(cell50);

          const cell5 = document.createElement('div');
          cell5.className = `mini-cell ${i < 5 ? 'active-green' : ''}`;
          grid5.appendChild(cell5);
        }
      }

      // 事件监听
      slider.addEventListener('input', (e) => {
        updateView(parseInt(e.target.value));
      });

      btnCompare.addEventListener('click', () => {
        renderMiniGrids();
        compareModal.classList.add('active');
      });

      btnClose.addEventListener('click', () => {
        compareModal.classList.remove('active');
      });

      // 初始化执行
      initGrid();
      initSvgLine();
      updateView(0);
    });
  </script>
</body>
