        const feedbackMsg = document.getElementById('feedback-msg');
        const resetBtn = document.getElementById('resetBtn');

        const partFree = document.getElementById('part-free');
        const partTax = document.getElementById('part-tax');
        const taxBracket = document.getElementById('tax-bracket');
        const taxBracketLabel = document.getElementById('tax-bracket-label');

        // 烟花画布设置
        const canvas = document.getElementById('effect-canvas');
        const ctx = canvas.getContext('2d');
        let particles = [];
        let animationFrameId = null;

        function resizeCanvas() {
            canvas.width = canvas.offsetWidth;
            canvas.height = canvas.offsetHeight;
        }
        window.addEventListener('resize', resizeCanvas);
        resizeCanvas();

        // 粒子类
        class Particle {
            constructor(x, y) {
                this.x = x;
                this.y = y;
                this.size = Math.random() * 6 + 4;
                this.speedX = Math.random() * 10 - 5;
                this.speedY = Math.random() * -12 - 4;
                this.gravity = 0.3;
                this.color = `hsl(${Math.random() * 360}, 90%, 60%)`;
                this.alpha = 1;
                this.decay = Math.random() * 0.015 + 0.01;
            }
            update() {
                this.speedY += this.gravity;
                this.x += this.speedX;
                this.y += this.speedY;
                this.alpha -= this.decay;
            }
            draw() {
                ctx.save();
                ctx.globalAlpha = this.alpha;
                ctx.fillStyle = this.color;
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
            }
        }

        function createExplosion(x, y) {
            for (let i = 0; i < 80; i++) {
