        function animateParticles() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            for (let i = particles.length - 1; i >= 0; i--) {
                const p = particles[i];
                p.update();
                p.draw();
                if (p.alpha <= 0) {
                    particles.splice(i, 1);
                }
            }
            if (particles.length > 0) {
                animationFrameId = requestAnimationFrame(animateParticles);
            }
        }

        // 交互逻辑
        cardWrong.addEventListener('click', () => {
            if (cardWrong.classList.contains('incorrect') || cardRight.classList.contains('correct')) return;

            // 错误反馈
            cardWrong.classList.add('incorrect');
            feedbackMsg.textContent = "不对哦！8500元里有5000元是免税的，免税部分不需要交税！";
            feedbackMsg.className = "feedback-text error";

            // 视觉辅助：高亮免税部分，弱化纳税部分
            partFree.setAttribute('fill', '#ef4444');
            partTax.setAttribute('fill', '#cbd5e1');
        });

        cardRight.addEventListener('click', (e) => {
            if (cardRight.classList.contains('correct')) return;

            // 正确反馈
            cardRight.classList.add('correct');
            cardWrong.classList.add('incorrect');
            feedbackMsg.textContent = "完全正确！只乘需要纳税的 3500 元！";
            feedbackMsg.className = "feedback-text success";

            // 视觉辅助：高亮纳税部分
            partTax.setAttribute('fill', '#10b981');
            partFree.setAttribute('fill', '#94a3b8');
            taxBracket.setAttribute('stroke', '#10b981');
            taxBracketLabel.setAttribute('fill', '#10b981');
            taxBracketLabel.style.fontSize = "18px";

            // 触发烟花
            const rect = cardRight.getBoundingClientRect();
            const canvasRect = canvas.getBoundingClientRect();
            const x = rect.left + rect.width / 2 - canvasRect.left;
            const y = rect.top - canvasRect.top;

            cancelAnimationFrame(animationFrameId);
            particles = [];
            createExplosion(x, y);
            createExplosion(x - 100, y + 50);
            createExplosion(x + 100, y + 50);
            animateParticles();
        });

        // 重置
        resetBtn.addEventListener('click', () => {
            cardWrong.classList.remove('incorrect');
            cardRight.classList.remove('correct');
            feedbackMsg.textContent = "请点击上方公式，选择你认为正确的计算方式。";
            feedbackMsg.className = "feedback-text";

