            partFree.setAttribute('fill', '#94a3b8');
            partTax.setAttribute('fill', '#f59e0b');
            taxBracket.setAttribute('stroke', '#f59e0b');
            taxBracketLabel.setAttribute('fill', '#f59e0b');
            taxBracketLabel.style.fontSize = "14px";

            // 清除画布
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            particles = [];
            cancelAnimationFrame(animationFrameId);
        });
    </script>
