    <script>
        const btnCalc = document.getElementById('btn-calc');
        const btnReset = document.getElementById('btn-reset');

        const barGrain = document.getElementById('bar-grain');
        const barCosmetic = document.getElementById('bar-cosmetic');

        const valGrain = document.getElementById('val-grain');
        const valCosmetic = document.getElementById('val-cosmetic');

        const formulaGrain = document.getElementById('formula-grain');
        const formulaCosmetic = document.getElementById('formula-cosmetic');

        // 映射比例：1元 = 6像素高度 (最大30元 = 180像素)
        const SCALE = 6; 

        btnCalc.addEventListener('click', () => {
            // 1. 柱状图伸展
            barGrain.style.height = `${9 * SCALE}px`;
            barCosmetic.style.height = `${30 * SCALE}px`;

            // 2. 数字渐现并跑表动画
            setTimeout(() => {
                valGrain.classList.add('show');
                valCosmetic.classList.add('show');
                animateValue(valGrain, 0, 9, 1000);
                animateValue(valCosmetic, 0, 30, 1000);
            }, 300);

            // 3. 公式渐现
            setTimeout(() => {
                formulaGrain.classList.add('show');
                formulaCosmetic.classList.add('show');
            }, 1000);

            // 禁用计算按钮，启用重置
            btnCalc.disabled = true;
            btnCalc.style.opacity = '0.5';
            btnCalc.style.cursor = 'not-allowed';
        });

        btnReset.addEventListener('click', () => {
            // 1. 恢复柱状图高度
            barGrain.style.height = '0px';
            barCosmetic.style.height = '0px';

            // 2. 隐藏并重置数字
            valGrain.classList.remove('show');
            valCosmetic.classList.remove('show');
            valGrain.innerText = '0 元';
            valCosmetic.innerText = '0 元';

            // 3. 隐藏公式
            formulaGrain.classList.remove('show');
            formulaCosmetic.classList.remove('show');

            // 恢复按钮状态
            btnCalc.disabled = false;
            btnCalc.style.opacity = '1';
            btnCalc.style.cursor = 'pointer';
        });

        // 数字递增动画函数
        function animateValue(obj, start, end, duration) {
            let startTimestamp = null;
            const step = (timestamp) => {
                if (!startTimestamp) startTimestamp = timestamp;
                const progress = Math.min((timestamp - startTimestamp) / duration, 1);
                obj.innerHTML = Math.floor(progress * (end - start) + start) + ' 元';
                if (progress < 1) {
                    window.requestAnimationFrame(step);
                } else {
                    obj.innerHTML = end + ' 元';
                }
            };
            window.requestAnimationFrame(step);
        }
    </script>
