    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const cardGrain = document.getElementById('card-grain');
            const cardCosmetic = document.getElementById('card-cosmetic');
            const totalGrain = document.getElementById('total-grain');
            const totalCosmetic = document.getElementById('total-cosmetic');
            const btnCompare = document.getElementById('btn-compare-all');
            const btnReset = document.getElementById('btn-reset-view');
            const tipsText = document.getElementById('tips-text');

            // 移除呼吸灯提示
            function stopPulse() {
                totalGrain.classList.remove('pulse-hint');
                totalCosmetic.classList.remove('pulse-hint');
            }

            // 激活粮食卡片
            function activateGrain() {
                stopPulse();
                cardGrain.classList.add('active', 'active-grain');
                cardCosmetic.classList.remove('active', 'active-cosmetic');
                tipsText.innerHTML = '<strong>粮食税率低 (9%)</strong>，税额仅 9 元，最终总价 109 元。';
            }

            // 激活化妆品卡片
            function activateCosmetic() {
                stopPulse();
                cardCosmetic.classList.add('active', 'active-cosmetic');
                cardGrain.classList.remove('active', 'active-grain');
                tipsText.innerHTML = '<strong>化妆品税率高 (30%)</strong>，税额高达 30 元，最终总价 130 元！';
            }

            // 同时对比
            function activateBoth() {
                stopPulse();
                cardGrain.classList.add('active', 'active-grain');
                cardCosmetic.classList.add('active', 'active-cosmetic');
                tipsText.innerHTML = '对比发现：原价相同，<strong>税率越高</strong>，交的税就<strong>越多</strong>，商品总价就<strong>越高</strong>。';
            }

            // 重置
            function resetAll() {
                cardGrain.classList.remove('active', 'active-grain');
                cardCosmetic.classList.remove('active', 'active-cosmetic');
                totalGrain.classList.add('pulse-hint');
                totalCosmetic.classList.add('pulse-hint');
                tipsText.innerText = '请点击任意一侧的【实付总额】开始探究。';
            }

            // 绑定点击事件
            totalGrain.addEventListener('click', (e) => {
                e.stopPropagation();
                activateGrain();
            });

            totalCosmetic.addEventListener('click', (e) => {
                e.stopPropagation();
                activateCosmetic();
            });

            btnCompare.addEventListener('click', activateBoth);
            btnReset.addEventListener('click', resetAll);

            // 点击卡片空白处也能触发对应激活
            cardGrain.addEventListener('click', activateGrain);
            cardCosmetic.addEventListener('click', activateCosmetic);
        });
    </script>
