    // SVG 元素
    const bgWall = document.getElementById('bg-wall');
    const sunLight = document.getElementById('sun-light');
    const foodRich = document.getElementById('food-rich');
    const mainRice = document.getElementById('main-rice');
    const riceL = document.getElementById('rice-l');
    const riceR = document.getElementById('rice-r');
    const priceText = document.getElementById('price-text');

    // 人物表情元素
    const faMouth = document.getElementById('fa-mouth');
    const moMouth = document.getElementById('mo-mouth');
    const chMouth = document.getElementById('ch-mouth');
    const faBrowL = document.getElementById('fa-brow-l');
    const faBrowR = document.getElementById('fa-brow-r');
    const moBrowL = document.getElementById('mo-brow-l');
    const moBrowR = document.getElementById('mo-brow-r');
    const faTear = document.getElementById('fa-tear');
    const moTear = document.getElementById('mo-tear');

    // Web Audio API 变量
    let audioCtx = null;
    let osc1 = null, osc2 = null, osc3 = null;
    let gainNode = null;
    let filterNode = null;

    // 初始化 Web Audio
    function initAudio() {
        if (audioCtx) return;
        audioCtx = new (window.AudioContext || window.webkitAudioContext)();

        // 低通滤波器，用于控制音色明暗
        filterNode = audioCtx.createBiquadFilter();
        filterNode.type = 'lowpass';
        filterNode.frequency.setValueAtTime(800, audioCtx.currentTime);

        // 主音量控制
        gainNode = audioCtx.createGain();
        gainNode.gain.setValueAtTime(0.08, audioCtx.currentTime); // 保持温和的音量

        // 创建三个振荡器合成和弦
        osc1 = audioCtx.createOscillator();
        osc2 = audioCtx.createOscillator();
        osc3 = audioCtx.createOscillator();

        osc1.type = 'triangle';
        osc2.type = 'triangle';
        osc3.type = 'triangle';

        // 初始和弦：C大和弦 (C4, E4, G4) -> 温暖明亮
        osc1.frequency.setValueAtTime(261.63, audioCtx.currentTime);
        osc2.frequency.setValueAtTime(329.63, audioCtx.currentTime);
        osc3.frequency.setValueAtTime(392.00, audioCtx.currentTime);

        // 连接节点
        osc1.connect(gainNode);
        osc2.connect(gainNode);
        osc3.connect(gainNode);
        gainNode.connect(filterNode);
        filterNode.connect(audioCtx.destination);

        osc1.start();
        osc2.start();
        osc3.start();
    }

    // 更新音效
    function updateAudio(taxRate) {
        if (!audioCtx) return;
        if (audioCtx.state === 'suspended') {
            audioCtx.resume();
        }

        // 归一化比例 (0 到 1)
        const t = (taxRate - 9) / 21;

        // 频率插值：从 C大和弦(温暖) 渐变到 C小和弦且降低八度(低沉、忧郁)
