        const f1 = 261.63 * (1 - t) + 130.81 * t;
        const f2 = 329.63 * (1 - t) + 155.56 * t;
        const f3 = 392.00 * (1 - t) + 196.00 * t;

        osc1.frequency.setTargetAtTime(f1, audioCtx.currentTime, 0.1);
        osc2.frequency.setTargetAtTime(f2, audioCtx.currentTime, 0.1);
        osc3.frequency.setTargetAtTime(f3, audioCtx.currentTime, 0.1);

        // 滤波器截止频率：从明亮(1200Hz)到沉闷(200Hz)
        const cutoff = 1000 * (1 - t) + 200 * t;
        filterNode.frequency.setTargetAtTime(cutoff, audioCtx.currentTime, 0.1);
    }

    // 更新视觉和文本状态
    function updateVisualization(taxRate) {
        taxDisplay.textContent = taxRate + '%';

        if (taxRate >= 25) {
            taxDisplay.className = 'tax-value high';
        } else {
            taxDisplay.className = 'tax-value';
