        // 3. 墙面颜色渐变 (温暖黄色 -> 阴冷灰色)
        const r = Math.round(255 * (1 - t) + 207 * t);
        const g = Math.round(253 * (1 - t) + 216 * t);
        const b = Math.round(231 * (1 - t) + 220 * t);
        bgWall.setAttribute('fill', `rgb(${r}, ${g}, ${b})`);
        sunLight.setAttribute('opacity', (0.6 * (1 - t)).toString());

        // 4. 食物消失度
        foodRich.setAttribute('opacity', (1 - t * 1.2).toString()); // 丰盛食物完全消失

        // 粮食变少
        const riceScale = 1 - t * 0.6;
        mainRice.setAttribute('transform', `translate(300, 355) scale(${riceScale}) translate(-300, -355)`);
        riceL.setAttribute('opacity', (1 - t * 0.7).toString());
        riceR.setAttribute('opacity', (1 - t * 0.7).toString());

        // 5. 人物表情与眼泪
        if (taxRate <= 12) {
            // 幸福微笑
            faMouth.setAttribute('d', 'M -12 20 Q 0 30 12 20');
            moMouth.setAttribute('d', 'M -10 20 Q 0 28 10 20');
            chMouth.setAttribute('d', 'M -8 14 Q 0 22 8 14');

            faBrowL.setAttribute('d', 'M -16 -3 Q -10 -8 -4 -3');
            faBrowR.setAttribute('d', 'M 4 -3 Q 10 -8 16 -3');
            moBrowL.setAttribute('d', 'M -14 -2 Q -9 -6 -4 -2');
            moBrowR.setAttribute('d', 'M 4 -2 Q 9 -6 14 -2');

            faTear.setAttribute('opacity', '0');
            moTear.setAttribute('opacity', '0');

            statusText.innerHTML = `<strong>当前状态：丰衣足食</strong><br>粮食税率为 9%（国家保护性低税率）。百姓生活富足，餐桌上鸡鸭鱼肉样样俱全，家庭充满欢声笑语。`;
            warningBanner.classList.remove('show');

        } else if (taxRate > 12 && taxRate < 25) {
            // 逐渐忧虑
            faMouth.setAttribute('d', 'M -12 22 Q 0 22 12 22');
            moMouth.setAttribute('d', 'M -10 22 Q 0 22 10 22');
            chMouth.setAttribute('d', 'M -8 16 Q 0 16 8 16');

            // 眉头微锁
            faBrowL.setAttribute('d', 'M -16 -5 Q -10 -5 -4 -8');
            faBrowR.setAttribute('d', 'M 4 -8 Q 10 -5 16 -5');
            moBrowL.setAttribute('d', 'M -14 -4 Q -9 -4 -4 -7');
            moBrowR.setAttribute('d', 'M 4 -7 Q 9 -4 14 -4');

            faTear.setAttribute('opacity', '0');
            moTear.setAttribute('opacity', '0');

            statusText.innerHTML = `<strong>当前状态：精打细算</strong><br>税率提高到 ${taxRate}%。伙食开支明显增加，餐桌上的肉类和蔬菜变少了，大家开始感到生活压力。`;
            warningBanner.classList.remove('show');

        } else {
            // 极度难过/哭泣
            faMouth.setAttribute('d', 'M -12 25 Q 0 15 12 25');
            moMouth.setAttribute('d', 'M -10 24 Q 0 16 10 24');
            chMouth.setAttribute('d', 'M -8 18 Q 0 12 8 18');

            // 愁眉苦脸
            faBrowL.setAttribute('d', 'M -16 -8 Q -10 -3 -4 -2');
            faBrowR.setAttribute('d', 'M 4 -2 Q 10 -3 16 -8');
            moBrowL.setAttribute('d', 'M -14 -7 Q -9 -2 -4 -1');
            moBrowR.setAttribute('d', 'M 4 -1 Q 9 -2 14 -7');

            // 出现泪水
            faTear.setAttribute('opacity', '0.8');
            moTear.setAttribute('opacity', '0.8');

            statusText.innerHTML = `<strong>当前状态：饥寒交迫</strong><br>税率高达 ${taxRate}%！粮食价格飞涨，普通家庭难以负担，餐桌上只剩下稀粥，老百姓面临挨饿的困境。`;
            warningBanner.classList.add('show');
        }
    }

    // 监听滑块事件
    slider.addEventListener('input', (e) => {
        const val = parseInt(e.target.value);

        // 首次互动时初始化音频
        if (!audioCtx) {
